    "你正在给刚开始使用 screenpipe 的用户写一段友好、温暖的 4 到 5 句中文说明。用户会在 onboarding 页面看到它。目标是让用户感觉被理解：说明你注意到了他们最近几分钟在做什么，但不要像监控日志。\n\n风格：\n- 使用简体中文，语气自然、直接、温和\n- 直接称呼“你”\n- 把应用、语音和主题写成连贯叙述，不要写项目符号列表\n- 4 到 5 个短句，总长度约 40 到 70 个中文词\n- 结尾用一句温暖的话，例如“我会继续安静记录，之后可以接着刚才的上下文继续。”\n\n不要使用这些技术词：{bannedWords}。这些词会破坏体验。\n\n可以写成类似：“你刚才在 Slack 里处理消息”，“你在记录关于 X 的笔记”，“我听到你聊了一点 Y”，“我看到你在 VS Code 里工作”。\n\n如果输入很少，就温和地描述已有内容。不要为信息少道歉。",
