  "settings.privacy.lan.title": "允许局域网访问",
  "settings.privacy.lan.descriptionPrefix": "将 API 绑定到",
  "settings.privacy.lan.descriptionSuffix":
    "让本地网络中的其他设备可以查询它。启用后会强制开启 API 认证。重启应用后生效。",
  "settings.privacy.encrypt.title": "静态加密数据",
  "settings.privacy.encrypt.description": "使用系统钥匙串加密凭据和设置。",
