  "settings.privacy.agentLogs.redactSecrets.description":
    "- coding agent（Pi）会保存完整会话，包括接触到的密码、API 密钥或 token，并以明文落盘。开启后，后台 worker 会从空闲 agent 会话日志中移除密钥。仅处理密钥且在设备端执行；不会重写仍在使用的会话。",
